CREATE TABLE public.seller_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid UNIQUE, business_name text NOT NULL, phone text NOT NULL DEFAULT '', location text NOT NULL DEFAULT 'Kampala', bio text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.seller_profiles TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.seller_profiles TO authenticated; GRANT ALL ON public.seller_profiles TO service_role;
ALTER TABLE public.seller_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY seller_public ON public.seller_profiles FOR SELECT USING (true);
CREATE POLICY seller_create ON public.seller_profiles FOR INSERT TO authenticated WITH CHECK (owner_id=auth.uid());
CREATE POLICY seller_update ON public.seller_profiles FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seller_id uuid NOT NULL REFERENCES public.seller_profiles(id), category text NOT NULL CHECK(category IN ('electronics','foods','fashion','transport','property','bridals')), title text NOT NULL, description text NOT NULL DEFAULT '', price numeric NOT NULL CHECK(price>=0), old_price numeric, location text NOT NULL DEFAULT 'Kampala', condition text NOT NULL DEFAULT 'New', image_url text NOT NULL DEFAULT '', photo_paths text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','draft','sold')), featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.listings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.listings TO authenticated; GRANT ALL ON public.listings TO service_role;
ALTER TABLE public.listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY listing_public ON public.listings FOR SELECT USING(status='active');
CREATE POLICY listing_owner_read ON public.listings FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.seller_profiles s WHERE s.id=seller_id AND s.owner_id=auth.uid()));
CREATE POLICY listing_owner_insert ON public.listings FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.seller_profiles s WHERE s.id=seller_id AND s.owner_id=auth.uid()));
CREATE POLICY listing_owner_update ON public.listings FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.seller_profiles s WHERE s.id=seller_id AND s.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.seller_profiles s WHERE s.id=seller_id AND s.owner_id=auth.uid()));
CREATE POLICY listing_owner_delete ON public.listings FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.seller_profiles s WHERE s.id=seller_id AND s.owner_id=auth.uid()));
CREATE INDEX listing_seller_idx ON public.listings(seller_id); CREATE INDEX listing_category_idx ON public.listings(category,status);
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, buyer_id uuid NOT NULL, seller_user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(listing_id,buyer_id), CHECK(buyer_id<>seller_user_id));
GRANT SELECT,INSERT ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_read ON public.conversations FOR SELECT TO authenticated USING(auth.uid() IN (buyer_id,seller_user_id));
CREATE POLICY conversation_insert ON public.conversations FOR INSERT TO authenticated WITH CHECK(buyer_id=auth.uid() AND EXISTS(SELECT 1 FROM public.listings l JOIN public.seller_profiles s ON s.id=l.seller_id WHERE l.id=listing_id AND l.status='active' AND s.owner_id=seller_user_id));
CREATE INDEX conversation_buyer_idx ON public.conversations(buyer_id); CREATE INDEX conversation_seller_idx ON public.conversations(seller_user_id);
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND auth.uid() IN (c.buyer_id,c.seller_user_id)));
CREATE POLICY message_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND auth.uid() IN (c.buyer_id,c.seller_user_id)));
CREATE INDEX message_conversation_idx ON public.messages(conversation_id,created_at);
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages;
CREATE TABLE public.favorites (user_id uuid NOT NULL, listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, PRIMARY KEY(user_id,listing_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorites_read ON public.favorites FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY favorites_add ON public.favorites FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid()); CREATE POLICY favorites_remove ON public.favorites FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE POLICY photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='listing-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY photo_read ON storage.objects FOR SELECT USING(bucket_id='listing-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.listings l WHERE l.status='active' AND name=ANY(l.photo_paths))));
CREATE POLICY photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='listing-photos' AND (storage.foldername(name))[1]=auth.uid()::text);